// Theme picker. Load in <head> after the stylesheets: it applies the saved theme before first paint,
// then adds a "Theme" menu to the header. Themes are defined in themes.css (generated by
// tools/build-themes.js). Reusable: set window.THEME_OPTIONS before this script to change the list,
// and window.THEME_MOUNT (a CSS selector) to change where the menu goes.
(() => {
  const KEY = "cert-theme";
  const OPTIONS = window.THEME_OPTIONS || [["system", "System"], ["dark", "Dark"], ["light", "Light"], ["contrast", "High contrast"], ["sepia", "Sepia"]];
  const valid = new Set(OPTIONS.map(o => o[0]));
  const read = () => { try { const v = localStorage.getItem(KEY); return valid.has(v) ? v : "system"; } catch { return "system"; } };
  const apply = (v) => {
    document.documentElement.dataset.theme = v;
    const sel = document.getElementById("themeSelect"); if (sel && sel.value !== v) sel.value = v;
    const meta = document.querySelector('meta[name="theme-color"]') || Object.assign(document.createElement("meta"), {name: "theme-color"});
    if (!meta.parentNode) document.head.appendChild(meta);
    requestAnimationFrame(() => { meta.content = getComputedStyle(document.body || document.documentElement).backgroundColor; });
  };
  apply(read());

  function mount() {
    if (document.getElementById("themeSelect")) return;
    const host = document.querySelector(window.THEME_MOUNT || "header .badges") || document.querySelector("header");
    if (!host) return;
    const label = document.createElement("label");
    label.className = "theme-picker";
    label.innerHTML = `<span>Theme</span><select id="themeSelect" aria-label="Color theme">${OPTIONS.map(([v, t]) => `<option value="${v}">${t}</option>`).join("")}</select>`;
    const select = label.querySelector("select");
    select.value = read();
    select.onchange = () => { try { localStorage.setItem(KEY, select.value); } catch {} apply(select.value); };
    const track = host.querySelector("select");
    if (track) track.insertAdjacentElement("afterend", label); else host.prepend(label);
  }
  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", mount); else mount();
  window.CertTheme = {apply, read, options: OPTIONS};
})();
